"""Run the full analysis: audit of the original notebooks, direction experiments, volatility model.

Writes results/summary.md and the figures in images/.
usage: python run_analysis.py
"""
from pathlib import Path

from analysis import data, evaluate, features, plots

ROOT = Path(__file__).resolve().parent
TICKERS = ["GOOGL", "MSFT"]


def summary(results, identical, mentions):
    lines = ["# Results", "",
             "Generated by `run_analysis.py`. Walk-forward test: each day is predicted by a model refit on all "
             "earlier days (late July to December 2023, 109 trading days per ticker).", "",
             "## Data checks", "",
             f"- Google and Microsoft news files identical apart from `Query`: **{identical}**",
             f"- Share of headlines mentioning Google or Alphabet: **{mentions:.1%}**", ""]

    lines += ["## Original setup, reproduced", "", "| | " + " | ".join(TICKERS) + " |", "|---|" + "---|" * len(TICKERS)]
    audit_rows = [("Accuracy with the label built from its own inputs", "circular_accuracy", "{:.1%}"),
                  ("Same-day close R², decision tree", "same_day_r2_model", "{:.3f}"),
                  ("Same-day close R², (High + Low) / 2 with no model", "same_day_r2_midpoint", "{:.3f}")]
    for label, key, fmt in audit_rows:
        lines.append(f"| {label} | " + " | ".join(fmt.format(results[t]["audit"][key]) for t in TICKERS) + " |")

    lines += ["", "## Next-day direction", "", "| Features | Model | " +
              " | ".join(f"{t} acc | {t} AUC" for t in TICKERS) + " |", "|---|---|" + "---|---|" * len(TICKERS)]
    for i, (fname, mname, _, _) in enumerate(results[TICKERS[0]]["direction"][0]):
        cells = []
        for t in TICKERS:
            _, _, acc, auc = results[t]["direction"][0][i]
            cells += [f"{acc:.1%}", "-" if auc != auc else f"{auc:.3f}"]
        lines.append(f"| {fname} | {mname} | " + " | ".join(cells) + " |")
    lines.append("")
    for t in TICKERS:
        rho, p = results[t]["direction"][1]
        lines.append(f"- {t}: Spearman correlation between sentiment z-score and next-day return {rho:+.3f} (p = {p:.2f})")

    for t in TICKERS:
        lines += ["", f"## Next-day volatility (true range), {t}", "",
                  "| Model | MAE (pts) | MAE vs 20-day avg | Skill R² | Skill R², non-earnings days | Corr | AUC, high-vol days |",
                  "|---|---|---|---|---|---|---|"]
        for row in results[t]["volatility"][0]:
            lines.append(f"| {row['model']} | {row['mae']:.3f} | {row['mae_gain']:+.1%} | {row['skill']:+.3f} | "
                         f"{row['skill_no_earnings']:+.3f} | {row['corr']:.2f} | {row['auc_high_vol']:.2f} |")
    return "\n".join(lines) + "\n"


def main():
    identical, mentions = data.news_overlap()
    news = data.load_news()
    results = {}
    for ticker in TICKERS:
        prices = data.load_prices(ticker)
        daily = data.daily_sentiment(news, prices["Date"])
        df = features.build_features(prices, daily, ticker)
        results[ticker] = {
            "audit": evaluate.audit_original(prices, daily),
            "direction": evaluate.direction_results(df),
            "volatility": evaluate.volatility_results(df),
            "df": df,
        }

    text = summary(results, identical, mentions)
    (ROOT / "results").mkdir(exist_ok=True)
    (ROOT / "results" / "summary.md").write_text(text, encoding="utf-8")
    plots.make_all(results, ROOT / "images")
    print(text)


if __name__ == "__main__":
    main()
